chrome.base_css:
*, ::before, ::after{box-sizing: border-box; margin: 0px; padding: 0px;}
:root{--aurora-deep: oklch(25% 0.15 300); --aurora-teal: oklch(75% 0.12 180); --aurora-pink: oklch(65% 0.2 330); --aurora-mid: oklch(35% 0.18 290); --aurora-glow: oklch(80% 0.14 185); --glass-bg: oklch(28% 0.08 290 / 0.35); --glass-border: oklch(75% 0.1 200 / 0.18); --glass-shine: oklch(90% 0.05 200 / 0.12); --text-primary: oklch(96% 0.02 200); --text-secondary: oklch(78% 0.06 210); --text-muted: oklch(60% 0.05 240); --font-weight: 300;}
html{scroll-behavior: smooth;}
body{font-family: Inter, system-ui, sans-serif; font-variation-settings: 'wght' var(--font-weight); background: var(--aurora-deep); color: var(--text-primary); min-height: 100vh; overflow-x: hidden; cursor: none;}
::selection{background: oklch(0.65 0.2 330 / 0.4); color: var(--text-primary);}
nav{position: fixed; top: 0px; left: 0px; right: 0px; z-index: 100; padding: 1.5rem max(2rem, 5vw); display: flex; align-items: center; justify-content: space-between; backdrop-filter: blur(40px) saturate(1.5); background: oklch(0.2 0.1 290 / 0.4); border-bottom: 1px solid var(--glass-border);}
footer{position: relative; z-index: 10; padding: 3rem max(2rem, 5vw); border-top: 1px solid var(--glass-border); display: flex; align-items: center; justify-content: space-between;}
@media (max-width: 900px){footer{flex-direction: column; gap: 1.5rem; text-align: center;}}

chrome.util_css:
.cursor{position: fixed; width: 12px; height: 12px; background: var(--aurora-teal); border-radius: 50%; pointer-events: none; z-index: 9999; mix-blend-mode: screen; transition: transform 0.15s, opacity 0.3s; transform: translate(-50%, -50%);}
.cursor-ring{position: fixed; width: 40px; height: 40px; border: 1px solid oklch(0.75 0.12 180 / 0.5); border-radius: 50%; pointer-events: none; z-index: 9998; transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), width 0.3s, height 0.3s, border-color 0.3s; transform: translate(-50%, -50%);}
body:has(a:hover) .cursor-ring, body:has(button:hover) .cursor-ring{width: 60px; height: 60px; border-color: oklch(0.65 0.2 330 / 0.6);}
.scene{position: relative; min-height: 100vh;}
.bg-gradient{position: fixed; inset: 0px; background: radial-gradient(80% 60% at 20% 50%, oklch(0.35 0.18 290 / 0.8) 0%, transparent 70%), radial-gradient(60% 80% at 80% 20%, oklch(0.4 0.15 220 / 0.6) 0%, transparent 60%), radial-gradient(70% 50% at 60% 80%, oklch(0.3 0.2 330 / 0.5) 0%, transparent 60%), oklch(0.18 0.1 290); z-index: 0;}
.aurora-layer{position: fixed; inset: 0px; z-index: 1; pointer-events: none; overflow: hidden;}
.aurora-band{position: absolute; border-radius: 50%; filter: blur(80px); animation: 20s ease-in-out 0s infinite normal none running aurora-drift; mix-blend-mode: screen; opacity: 0.35;}
.aurora-band:nth-child(1){width: 120%; height: 40%; top: 10%; left: -20%; background: linear-gradient(90deg, transparent 0%, oklch(0.75 0.12 180 / 0.6) 30%, oklch(0.65 0.15 200 / 0.4) 60%, transparent 100%); animation-delay: 0s; animation-duration: 25s;}
.aurora-band:nth-child(2){width: 100%; height: 35%; top: 25%; left: 10%; background: linear-gradient(90deg, transparent 0%, oklch(0.65 0.2 330 / 0.4) 20%, oklch(0.75 0.12 200 / 0.3) 70%, transparent 100%); animation-delay: -8s; animation-duration: 30s;}
.aurora-band:nth-child(3){width: 80%; height: 30%; top: 5%; right: -10%; background: linear-gradient(90deg, transparent 0%, oklch(0.55 0.18 260 / 0.5) 40%, oklch(0.65 0.15 310 / 0.3) 80%, transparent 100%); animation-delay: -15s; animation-duration: 22s;}
@keyframes aurora-drift { 
  0%, 100% { transform: translateX(0px) translateY(0px) scaleY(1); opacity: 0.35; }
  25% { transform: translateX(5%) translateY(3%) scaleY(1.2); opacity: 0.45; }
  50% { transform: translateX(-3%) translateY(-2%) scaleY(0.9); opacity: 0.3; }
  75% { transform: translateX(8%) translateY(1%) scaleY(1.1); opacity: 0.4; }
}
.video-portal{position: fixed; top: 50%; right: 5%; transform: translateY(-50%); width: clamp(280px, 35vw, 520px); height: clamp(380px, 55vh, 720px); z-index: 2; border-radius: 28px 8px; overflow: hidden; mask-image: radial-gradient(80% 90% at 60% 50%, black 30%, transparent 100%);}
.video-portal video{width: 100%; height: 100%; object-fit: cover; opacity: 0.7; filter: saturate(1.4) brightness(0.85);}
.video-portal-glow{position: fixed; top: 50%; right: 3%; transform: translateY(-50%); width: clamp(320px, 40vw, 580px); height: clamp(420px, 65vh, 800px); z-index: 1; background: radial-gradient(oklch(0.55 0.15 200 / 0.2) 0%, oklch(0.45 0.18 260 / 0.1) 50%, transparent 80%); border-radius: 40px; filter: blur(40px); pointer-events: none;}
.video-fallback-bg{position: absolute; inset: 0px; background: radial-gradient(60% 60% at 40% 40%, oklch(0.6 0.15 185) 0%, transparent 70%), radial-gradient(50% 50% at 70% 70%, oklch(0.55 0.2 310) 0%, transparent 60%), oklch(0.3 0.12 240); animation: 8s ease-in-out 0s infinite normal none running portal-shimmer;}
@keyframes portal-shimmer { 
  0%, 100% { filter: brightness(0.9) hue-rotate(0deg); }
  50% { filter: brightness(1.1) hue-rotate(15deg); }
}
.main-content{position: relative; z-index: 10; min-height: 100vh; padding: 0px max(2rem, 5vw); max-width: 55%;}
@keyframes logo-spin { 
  100% { transform: rotate(360deg); }
}
.hero{padding-top: clamp(8rem, 18vh, 14rem); padding-bottom: 4rem;}
.hero-eyebrow{display: flex; align-items: center; gap: 1rem; margin-bottom: 2rem; opacity: 0; animation: 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.2s 1 normal forwards running fade-up;}
.eyebrow-line{width: 40px; height: 1px; background: var(--aurora-teal);}
.eyebrow-text{font-size: 0.7rem; letter-spacing: 0.4em; text-transform: uppercase; color: var(--aurora-teal); font-variation-settings: "wght" 500;}
.hero-title{font-size: clamp(2.8rem, 6vw, 5.5rem); line-height: 0.95; letter-spacing: -0.04em; margin-bottom: 1.5rem; font-variation-settings: "wght" 200;}
.hero-title-line{display: block; overflow: hidden;}
.hero-title-line span{display: inline-block; opacity: 0; transform: translateY(100%); animation: 1s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal forwards running slide-up;}
.hero-title-line:nth-child(1) span{animation-delay: 0.4s;}
.hero-title-line:nth-child(2) span{animation-delay: 0.55s;}
.hero-title-line:nth-child(3) span{animation-delay: 0.7s;}
.hero-title .accent{color: transparent; -webkit-text-stroke: 1px oklch(0.75 0.12 180 / 0.7); font-variation-settings: "ital" 1, "wght" 100;}
.hero-sub{font-size: clamp(0.85rem, 1.2vw, 1rem); color: var(--text-secondary); line-height: 1.7; max-width: 38ch; margin-bottom: 3rem; font-variation-settings: "wght" 300; opacity: 0; animation: 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.9s 1 normal forwards running fade-up;}
.hero-actions{display: flex; gap: 1.25rem; align-items: center; opacity: 0; animation: 0.8s cubic-bezier(0.16, 1, 0.3, 1) 1.1s 1 normal forwards running fade-up;}
.btn-primary{position: relative; padding: 0.9rem 2.5rem; background: transparent; border: 0px; border-radius: 100px; color: var(--aurora-deep); font-family: inherit; font-size: 0.8rem; letter-spacing: 0.15em; text-transform: uppercase; cursor: none; overflow: hidden; font-variation-settings: "wght" 500; isolation: isolate;}
.btn-primary-bg{position: absolute; inset: 0px; background: linear-gradient(135deg, var(--aurora-teal), var(--aurora-glow)); border-radius: 100px; transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);}
.btn-primary:hover .btn-primary-bg{transform: scale(1.03);}
.btn-primary-liquid{position: absolute; inset: 0px; border-radius: 100px; background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
          oklch(90% 0.08 180 / 0.6) 0%,
          transparent 50%); opacity: 0; transition: opacity 0.3s;}
.btn-primary:hover .btn-primary-liquid{opacity: 1;}
.btn-primary span{position: relative; z-index: 1;}
.btn-ghost{position: relative; padding: 0.9rem 2rem; background: transparent; border: 1px solid var(--glass-border); border-radius: 100px; color: var(--text-secondary); font-family: inherit; font-size: 0.8rem; letter-spacing: 0.15em; text-transform: uppercase; cursor: none; font-variation-settings: "wght" 400; transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1); display: flex; align-items: center; gap: 0.75rem; overflow: hidden;}
.btn-ghost::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
          oklch(75% 0.12 180 / 0.1) 0%,
          transparent 60%); opacity: 0; transition: opacity 0.3s;}
.btn-ghost:hover{color: var(--text-primary); border-color: oklch(0.75 0.12 180 / 0.4);}
.btn-ghost:hover::before{opacity: 1;}
.stats-row{display: flex; gap: 3rem; margin-top: 5rem; padding-top: 3rem; border-top: 1px solid var(--glass-border); opacity: 0; animation: 0.8s cubic-bezier(0.16, 1, 0.3, 1) 1.3s 1 normal forwards running fade-up;}
.stat-item{}
.stat-value{font-size: clamp(1.8rem, 3vw, 2.4rem); font-variation-settings: "wght" 200; letter-spacing: -0.04em; color: var(--text-primary); line-height: 1; margin-bottom: 0.4rem;}
.stat-unit{font-size: 0.7em; color: var(--aurora-teal); font-variation-settings: "wght" 400;}
.stat-label{font-size: 0.68rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-muted);}
.bento-section{padding: 6rem 0px; position: relative; z-index: 10;}
.section-header{margin-bottom: 3rem;}
.section-eyebrow{display: flex; align-items: center; gap: 1rem; margin-bottom: 1rem;}
.section-title{font-size: clamp(2rem, 3.5vw, 3rem); font-variation-settings: "wght" 200; letter-spacing: -0.03em; line-height: 1.1;}
.bento-grid{display: grid; grid-template-columns: repeat(12, 1fr); grid-template-rows: auto; gap: 1rem;}
.bento-card{position: relative; background: var(--glass-bg); backdrop-filter: blur(100px) saturate(1.8); border: 1px solid var(--glass-border); border-radius: 20px; overflow: hidden; transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s; container-type: inline-size;}
.bento-card::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(135deg, oklch(0.9 0.05 200 / 0.08) 0%, transparent 50%, oklch(0.65 0.1 300 / 0.05) 100%); pointer-events: none; z-index: 1;}
.bento-card::after{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.9 0.05 200 / 0.3), transparent); z-index: 2;}
.bento-card:hover{transform: translateY(-4px) scale(1.005); box-shadow: oklch(0.15 0.15 290 / 0.5) 0px 32px 80px, oklch(0.9 0.05 200 / 0.15) 0px 1px 0px inset, oklch(0.5 0.1 270 / 0.1) 0px -1px 0px inset, oklch(0.75 0.12 180 / 0.1) 0px 0px 0px 1px;}
.bento-card-inner{position: relative; z-index: 3; height: 100%; padding: 1.75rem;}
.bc-hero{grid-column: span 7; min-height: 380px;}
.bc-tall{grid-column: span 5; min-height: 380px;}
.bc-wide{grid-column: span 8; min-height: 200px;}
.bc-sm{grid-column: span 4; min-height: 200px;}
.bc-med{grid-column: span 6; min-height: 260px;}
.bc-med-r{grid-column: span 6; min-height: 260px;}
.card-eyebrow{font-size: 0.65rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--aurora-teal); margin-bottom: 0.75rem; font-variation-settings: "wght" 500;}
.card-title{font-size: clamp(1.2rem, 2.5cqw, 1.8rem); font-variation-settings: "wght" 300; letter-spacing: -0.02em; line-height: 1.2; margin-bottom: 0.75rem;}
.card-desc{font-size: 0.82rem; color: var(--text-secondary); line-height: 1.65; font-variation-settings: "wght" 300;}
.card-meta{display: flex; align-items: center; gap: 1rem; margin-top: auto; padding-top: 1.5rem;}
.price-tag{font-size: 1.6rem; font-variation-settings: "wght" 200; letter-spacing: -0.04em; color: var(--text-primary);}
.price-sub{font-size: 0.7rem; color: var(--text-muted); letter-spacing: 0.1em;}
.badge{display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.3rem 0.75rem; border-radius: 100px; font-size: 0.65rem; letter-spacing: 0.15em; text-transform: uppercase; font-variation-settings: "wght" 500;}
.badge-teal{background: oklch(0.75 0.12 180 / 0.15); color: var(--aurora-teal); border: 1px solid oklch(0.75 0.12 180 / 0.25);}
.badge-pink{background: oklch(0.65 0.2 330 / 0.12); color: oklch(0.75 0.15 330); border: 1px solid oklch(0.65 0.2 330 / 0.25);}
.badge-dot{width: 5px; height: 5px; border-radius: 50%; background: currentcolor; animation: 2s ease-in-out 0s infinite normal none running pulse-dot;}
@keyframes pulse-dot { 
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.7); }
}
.card-visual{position: absolute; inset: 0px; pointer-events: none;}
.card-orb{position: absolute; border-radius: 50%; filter: blur(60px);}
.orb-teal{width: 200px; height: 200px; background: oklch(0.75 0.12 180 / 0.25); animation: 8s ease-in-out 0s infinite normal none running orb-float;}
.orb-pink{width: 150px; height: 150px; background: oklch(0.65 0.2 330 / 0.2); animation: 6s ease-in-out 0s infinite reverse none running orb-float;}
.orb-purple{width: 180px; height: 180px; background: oklch(0.55 0.18 280 / 0.3); animation: 10s ease-in-out 0s infinite normal none running orb-float;}
@keyframes orb-float { 
  0%, 100% { transform: translate(0px, 0px) scale(1); }
  33% { transform: translate(10%, -15%) scale(1.1); }
  66% { transform: translate(-8%, 10%) scale(0.95); }
}
.temp-display{font-size: clamp(3rem, 8cqw, 6rem); font-variation-settings: "wght" 100; letter-spacing: -0.06em; line-height: 1; color: var(--text-primary); margin: 0.5rem 0px;}
.temp-unit{font-size: 0.4em; color: var(--text-muted); vertical-align: super;}
.spec-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; margin-top: 1rem;}
.spec-item{padding: 0.75rem; background: oklch(0.3 0.1 290 / 0.4); border-radius: 10px; border: 1px solid oklch(0.7 0.08 200 / 0.1);}
.spec-val{font-size: 1.1rem; font-variation-settings: "wght" 300; letter-spacing: -0.02em; color: var(--text-primary);}
.spec-key{font-size: 0.62rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-muted); margin-top: 0.2rem;}
.gear-showcase{display: flex; flex-direction: column; height: 100%; gap: 1rem;}
.gear-item{flex: 1 1 0%; display: flex; align-items: center; gap: 1rem; padding: 1rem; background: oklch(0.28 0.08 290 / 0.4); border-radius: 12px; border: 1px solid var(--glass-border); transition: 0.3s cubic-bezier(0.16, 1, 0.3, 1); cursor: none;}
.gear-item:hover{background: oklch(0.32 0.1 290 / 0.6); border-color: oklch(0.75 0.12 180 / 0.3); transform: translateX(6px);}
.gear-icon{width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 1.3rem;}
.gear-icon-teal{background: oklch(0.75 0.12 180 / 0.15); color: var(--aurora-teal);}
.gear-icon-pink{background: oklch(0.65 0.2 330 / 0.12); color: oklch(0.75 0.15 330);}
.gear-icon-purple{background: oklch(0.55 0.18 280 / 0.15); color: oklch(0.75 0.12 280);}
.gear-name{font-size: 0.85rem; font-variation-settings: "wght" 400; color: var(--text-primary); margin-bottom: 0.2rem;}
.gear-detail{font-size: 0.7rem; color: var(--text-muted); letter-spacing: 0.05em;}
.gear-price{margin-left: auto; font-size: 0.9rem; font-variation-settings: "wght" 300; color: var(--aurora-teal); white-space: nowrap;}
.rating-bar{width: 100%; height: 2px; background: oklch(0.4 0.1 290 / 0.4); border-radius: 1px; margin-top: 1rem; overflow: hidden;}
.rating-fill{height: 100%; background: linear-gradient(90deg, var(--aurora-teal), var(--aurora-pink)); border-radius: 1px; width: 0px; transition: width 1.5s cubic-bezier(0.16, 1, 0.3, 1);}
.features-section{padding: 6rem 0px; position: relative; z-index: 10;}
.features-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 3rem;}
.feature-card{padding: 2rem; background: var(--glass-bg); backdrop-filter: blur(80px) saturate(1.6); border: 1px solid var(--glass-border); border-radius: 16px; transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1); cursor: none; position: relative; overflow: hidden;}
.feature-card::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.85 0.08 200 / 0.25), transparent);}
.feature-card:hover{transform: translateY(-6px); box-shadow: oklch(0.15 0.15 290 / 0.5) 0px 40px 100px, oklch(0.75 0.12 180 / 0.12) 0px 0px 0px 1px inset;}
.feature-icon-wrap{width: 52px; height: 52px; border-radius: 14px; display: flex; align-items: center; justify-content: center; margin-bottom: 1.5rem; font-size: 1.5rem; position: relative;}
.feature-icon-wrap::after{content: ""; position: absolute; inset: -1px; border-radius: 15px; padding: 1px; background: linear-gradient(135deg, oklch(0.75 0.12 180 / 0.4), oklch(0.65 0.2 330 / 0.2)); mask: linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px) content-box exclude, linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px);}
.feature-title{font-size: 1rem; font-variation-settings: "wght" 400; letter-spacing: -0.01em; margin-bottom: 0.6rem; color: var(--text-primary);}
.feature-desc{font-size: 0.8rem; color: var(--text-secondary); line-height: 1.65; font-variation-settings: "wght" 300;}
.testimonial-section{padding: 6rem 0px; position: relative; z-index: 10;}
.testimonial-card{padding: 3rem; background: var(--glass-bg); backdrop-filter: blur(100px) saturate(1.8); border: 1px solid var(--glass-border); border-radius: 24px; position: relative; overflow: hidden; max-width: 640px;}
.testimonial-card::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.85 0.08 200 / 0.3) 30%, oklch(0.75 0.15 330 / 0.2) 70%, transparent);}
.testimonial-quote{font-size: clamp(1.1rem, 1.8vw, 1.4rem); font-variation-settings: "wght" 200; letter-spacing: -0.02em; line-height: 1.5; color: var(--text-primary); margin-bottom: 2rem;}
.testimonial-mark{position: absolute; top: 2rem; right: 2rem; font-size: 5rem; font-variation-settings: "wght" 800; color: oklch(0.75 0.12 180 / 0.1); line-height: 1; font-family: Georgia, serif;}
.testimonial-author{display: flex; align-items: center; gap: 1rem;}
.author-avatar{width: 44px; height: 44px; border-radius: 50%; background: conic-gradient(from 0deg, var(--aurora-teal), var(--aurora-pink), var(--aurora-teal)); display: flex; align-items: center; justify-content: center; font-size: 0.85rem; font-variation-settings: "wght" 600; color: var(--aurora-deep);}
.author-name{font-size: 0.85rem; font-variation-settings: "wght" 500; color: var(--text-primary);}
.author-role{font-size: 0.72rem; color: var(--text-muted); letter-spacing: 0.08em;}
.cta-section{padding: 8rem 0px 6rem; position: relative; z-index: 10;}
.cta-block{position: relative; padding: 5rem; background: var(--glass-bg); backdrop-filter: blur(100px) saturate(1.8); border: 1px solid var(--glass-border); border-radius: 32px; overflow: hidden; max-width: 700px;}
.cta-block::before{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.85 0.08 200 / 0.35), oklch(0.75 0.15 330 / 0.25), transparent);}
.cta-orb{position: absolute; border-radius: 50%; filter: blur(80px); pointer-events: none;}
.cta-title{font-size: clamp(2.5rem, 5vw, 4rem); font-variation-settings: "wght" 200; letter-spacing: -0.04em; line-height: 1.05; margin-bottom: 1.25rem; position: relative; z-index: 1;}
.cta-sub{font-size: 0.9rem; color: var(--text-secondary); line-height: 1.7; max-width: 38ch; margin-bottom: 2.5rem; font-variation-settings: "wght" 300; position: relative; z-index: 1;}
.cta-actions{display: flex; gap: 1rem; position: relative; z-index: 1;}
.scroll-indicator{position: fixed; top: 0px; left: 0px; height: 2px; background: linear-gradient(90deg, var(--aurora-teal), var(--aurora-pink)); z-index: 200; transform-origin: left center; width: 0%; transition: width 0.1s linear;}
.particle-canvas{position: fixed; inset: 0px; z-index: 3; pointer-events: none; opacity: 0.5;}
@keyframes fade-up { 
  100% { opacity: 1; transform: translateY(0px); }
  0% { opacity: 0; transform: translateY(24px); }
}
@keyframes slide-up { 
  100% { opacity: 1; transform: translateY(0px); }
  0% { opacity: 0; transform: translateY(100%); }
}
.noise-overlay{position: fixed; inset: 0px; z-index: 4; pointer-events: none; opacity: 0.025; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(https://openhero.art/api/%23noise)'/%3E%3C/svg%3E"); background-repeat: repeat; background-size: 256px 256px;}
.reveal{opacity: 0; transform: translateY(30px); transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal.visible{opacity: 1; transform: none;}
.reveal-delay-1{transition-delay: 0.1s;}
.reveal-delay-2{transition-delay: 0.2s;}
.reveal-delay-3{transition-delay: 0.3s;}
.deboss-card{box-shadow: oklch(0.1 0.1 290 / 0.5) 0px 2px 4px inset, oklch(0.8 0.05 200 / 0.08) 0px -1px 0px inset, oklch(0.8 0.05 200 / 0.05) 1px 0px 0px inset, oklch(0.1 0.1 290 / 0.3) -1px 0px 0px inset, oklch(0.12 0.12 290 / 0.4) 0px 20px 60px;}
.shine-bar{position: absolute; top: 0px; left: -100%; width: 60%; height: 1px; background: linear-gradient(90deg, transparent, oklch(0.9 0.05 200 / 0.5), transparent); animation: 4s ease-in-out 0s infinite normal none running shine-sweep;}
@keyframes shine-sweep { 
  0% { left: -60%; }
  60%, 100% { left: 120%; }
}
@media (max-width: 900px){.main-content{max-width: 100%;}}
@media (max-width: 900px){.video-portal{display: none;}}
@media (max-width: 900px){.video-portal-glow{display: none;}}
@media (max-width: 900px){.bc-hero{grid-column: span 12;}}
@media (max-width: 900px){.bc-tall{grid-column: span 12;}}
@media (max-width: 900px){.bc-wide{grid-column: span 12;}}
@media (max-width: 900px){.bc-sm{grid-column: span 12;}}
@media (max-width: 900px){.bc-med{grid-column: span 12;}}
@media (max-width: 900px){.bc-med-r{grid-column: span 12;}}
@media (max-width: 900px){.features-grid{grid-template-columns: 1fr;}}
@media (max-width: 900px){.stats-row{gap: 1.5rem; flex-wrap: wrap;}}
@media (max-width: 900px){.cta-block{padding: 2.5rem 1.5rem;}}

chrome.header_css:
.nav-logo{font-size: clamp(1rem, 1.4vw, 1.2rem); font-variation-settings: "wght" 600; letter-spacing: 0.3em; text-transform: uppercase; color: var(--text-primary); text-decoration: none; display: flex; align-items: center; gap: 0.75rem;}
.nav-logo-mark{width: 28px; height: 28px; background: conic-gradient(from 180deg,
          var(--aurora-teal),
          var(--aurora-pink),
          var(--aurora-teal)); border-radius: 6px; animation: 12s linear 0s infinite normal none running logo-spin;}
.nav-links{display: flex; gap: 2.5rem; list-style: none;}
.nav-links a{color: var(--text-secondary); text-decoration: none; font-size: 0.8rem; letter-spacing: 0.15em; text-transform: uppercase; transition: color 0.3s; position: relative;}
.nav-links a::after{content: ""; position: absolute; bottom: -4px; left: 0px; width: 0px; height: 1px; background: var(--aurora-teal); transition: width 0.4s cubic-bezier(0.16, 1, 0.3, 1);}
.nav-links a:hover{color: var(--text-primary);}
.nav-links a:hover::after{width: 100%;}
.nav-cta{padding: 0.5rem 1.25rem; border: 1px solid var(--glass-border); border-radius: 100px; color: var(--text-primary); text-decoration: none; font-size: 0.75rem; letter-spacing: 0.1em; text-transform: uppercase; backdrop-filter: blur(20px); background: var(--glass-shine); transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1); position: relative; overflow: hidden;}
.nav-cta::before{content: ""; position: absolute; inset: -100%; background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
          oklch(75% 0.12 180 / 0.3) 0%,
          transparent 60%); transition: opacity 0.3s; opacity: 0;}
.nav-cta:hover::before{opacity: 1;}
.nav-cta:hover{border-color: oklch(0.75 0.12 180 / 0.5); box-shadow: oklch(0.75 0.12 180 / 0.15) 0px 0px 30px;}

chrome.footer_css:
.footer-copy{font-size: 0.72rem; color: var(--text-muted); letter-spacing: 0.1em;}
.footer-links{display: flex; gap: 2rem;}
.footer-links a{font-size: 0.72rem; color: var(--text-muted); text-decoration: none; letter-spacing: 0.1em; transition: color 0.3s;}
.footer-links a:hover{color: var(--text-secondary);}
